package org.sleepwell.app;

import android.content.Context;import android.graphics.*;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.function.BooleanSupplier;

/** Native original counting and flag artwork used unchanged in alarm and silent preview. */
final class WakePuzzleView {
    static void math(LinearLayout card,String run,int unit,int round,BooleanSupplier current,Runnable complete){MathTask puzzle=MathTask.create(new java.util.Random(CountingPuzzle.seed(run,unit,round,"math-preview")),MathSettings.LEGACY);Design.text(card,"Math alternative",20,600,Design.INK);Design.text(card,puzzle.question(),34,600,Design.BROWN);EditText input=new EditText(card.getContext());input.setContentDescription("Preview Math answer");input.setInputType(InputType.TYPE_CLASS_NUMBER);input.setSingleLine(true);card.addView(input,new LinearLayout.LayoutParams(-1,-2));TextView feedback=Design.text(card,"",13,500,Design.BROWN);Design.button(card,"Check Math answer",true,()->{if(!current.getAsBoolean())return;if(puzzle.acceptsTyped(input.getText().toString()))complete.run();else feedback.setText("Try again.");});}
    static EditText counting(LinearLayout card,String run,int unit,int round,Bundle restored,BooleanSupplier current,Runnable complete){CountingPuzzle puzzle=CountingPuzzle.create(run,unit,round);Design.text(card,"How many "+puzzle.targetName()+"?",23,600,Design.INK);Design.space(card,12);card.addView(new ShapeBoard(card.getContext(),puzzle),new LinearLayout.LayoutParams(-1,-2));Design.space(card,12);EditText input=new EditText(card.getContext());input.setContentDescription("Counting answer");input.setHint("Enter the count");input.setInputType(InputType.TYPE_CLASS_NUMBER);input.setSingleLine(true);input.setTextSize(25*Appearance.scale(card.getContext()));input.setTypeface(Design.font(card.getContext(),600));input.setTextColor(Design.INK);input.setHintTextColor(Design.MUTED);input.setBackground(Design.outline(card.getContext(),Design.SOFT,Design.LINE,16));Design.pad(input,14,14);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(2)});String key=ChallengePackState.key(run,unit,round);if(restored!=null&&key.equals(restored.getString("countKey")))input.setText(restored.getString("countAnswer",""));card.addView(input,new LinearLayout.LayoutParams(-1,-2));TextView feedback=Design.text(card,"",13,500,Design.BROWN);Design.button(card,"Check count",true,()->{if(!current.getAsBoolean())return;if(puzzle.accepts(input.getText().toString()))complete.run();else feedback.setText("Count only the "+puzzle.targetName()+" and try again.");});return input;}
    static void flags(LinearLayout card,String run,int unit,int round,BooleanSupplier current,Runnable complete){FlagPuzzle puzzle=FlagPuzzle.create(run,unit,round);Design.text(card,"Which country's flag is this?",22,600,Design.INK);Design.space(card,18);FlagArt art=new FlagArt(card.getContext(),puzzle.target);art.setContentDescription("Flag to identify");card.addView(art,new LinearLayout.LayoutParams(-1,-2));Design.space(card,18);TextView feedback=Design.text(card,"",13,500,Design.BROWN);for(int option:puzzle.choices)Design.button(card,FlagPuzzle.COUNTRIES.get(option),false,()->{if(!current.getAsBoolean())return;if(puzzle.accepts(option))complete.run();else feedback.setText("Try another country.");});}
    private static final class ShapeBoard extends View {
        final CountingPuzzle puzzle;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);
        ShapeBoard(Context context,CountingPuzzle puzzle){super(context);this.puzzle=puzzle;StringBuilder accessible=new StringBuilder("Counting board. ");for(int n=0;n<puzzle.size();n++)accessible.append("Row ").append(n/puzzle.columns+1).append(" column ").append(n%puzzle.columns+1).append(": ").append(CountingPuzzle.name(puzzle.shape(n))).append(". ");setContentDescription(accessible);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);}
        protected void onMeasure(int width,int height){int size=MeasureSpec.getSize(width);setMeasuredDimension(size,size);}
        protected void onDraw(Canvas canvas){float cell=getWidth()/(float)puzzle.columns;paint.setColor(Design.SOFT);canvas.drawRoundRect(0,0,getWidth(),getHeight(),20,20,paint);for(int n=0;n<puzzle.size();n++){float x=(n%puzzle.columns+.5f)*cell,y=(n/puzzle.columns+.5f)*cell,r=cell*.25f;paint.setColor(0xff8751ce);switch(puzzle.shape(n)){case 0->canvas.drawCircle(x,y,r,paint);case 1->{Path path=new Path();path.moveTo(x,y-r);path.lineTo(x+r,y);path.lineTo(x,y+r);path.lineTo(x-r,y);path.close();canvas.drawPath(path,paint);}case 2->{Path path=new Path();path.moveTo(x,y-r);path.lineTo(x+r,y+r);path.lineTo(x-r,y+r);path.close();canvas.drawPath(path,paint);}}}}
    }
    private static final class FlagArt extends View {
        final int country;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);
        FlagArt(Context context,int country){super(context);this.country=country;}
        protected void onMeasure(int width,int height){int size=MeasureSpec.getSize(width);setMeasuredDimension(size,(int)(size*2/3f));}
        private void rect(Canvas c,float x,float y,float w,float h,int color){paint.setColor(color);c.drawRect(x*getWidth(),y*getHeight(),(x+w)*getWidth(),(y+h)*getHeight(),paint);}
        protected void onDraw(Canvas c){rect(c,0,0,1,1,Color.WHITE);switch(country){case 0->{paint.setColor(0xffbc002d);c.drawCircle(getWidth()*.5f,getHeight()*.5f,getHeight()*.3f,paint);}case 1->{rect(c,0,0,1/3f,1,0xff002395);rect(c,2/3f,0,1/3f,1,0xffed2939);}case 2->{rect(c,0,0,1/3f,1,0xff009246);rect(c,2/3f,0,1/3f,1,0xffce2b37);}case 3->{rect(c,0,0,1,1/3f,0xff000000);rect(c,0,1/3f,1,1/3f,0xffdd0000);rect(c,0,2/3f,1,1/3f,0xffffce00);}case 4->rect(c,0,.5f,1,.5f,0xffdc143c);case 5->{rect(c,0,0,1,.5f,0xff0057b7);rect(c,0,.5f,1,.5f,0xffffd700);}case 6->{rect(c,0,0,1,1,0xff006aa7);rect(c,.30f,0,.12f,1,0xfffecc00);rect(c,0,.42f,1,.16f,0xfffecc00);}case 7->{rect(c,.30f,0,.16f,1,0xff003580);rect(c,0,.40f,1,.2f,0xff003580);}}paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2);paint.setColor(Design.LINE);c.drawRect(1,1,getWidth()-1,getHeight()-1,paint);paint.setStyle(Paint.Style.FILL);}
    }
}
